{
  "verdict": "REVISE",
  "findings": [
    {
      "severity": "critical",
      "claim": "Vector Search coverage=full, evidence_status=declared",
      "problem": "The passport claims 'full' coverage for Vector Search based on 'optional neural embedders'. However, the README explicitly states the default embedder is 'lexical, offline' and neural embedders are 'opt-in, downloads ~90 MB'. Declaring full capability without the optional dependency present is misleading. The evidence_status 'declared' relies on README marketing text rather than code verification of the vector search implementation itself.",
      "evidence": "README.md@50e4ffde: '[![Default embedder](https://img.shields.io/badge/default%20embedder-lexical,%20offline-teal?style=flat-square)]... [![Neural](https://img.shields.io/badge/neural%20embedder-opt--in,%20downloads%20~90%20MB-9c6ade?style=flat-square)]'",
      "suggested_fix": "Change coverage to 'partial' or 'none' for the base artifact, or explicitly state that Vector Search requires an optional dependency. Change evidence_status to 'inferred' if relying on README."
    },
    {
      "severity": "high",
      "claim": "Elasticsearch-Compatible API coverage=full, evidence_status=declared",
      "problem": "The claim of ES-compatibility is marked 'declared' with evidence from README and Dockerfile. The Dockerfile only exposes port 9200; it does not contain code verifying the API protocol conformance. While the README mentions 'ES-YAML conformance', the passport's own evidence section lists this claim as 'verified: false'. A 'full' coverage claim requires stronger evidence than just a port exposure and marketing badges.",
      "evidence": "engine/Dockerfile@50e4ffde (EXPOSE 9200); Evidence section: {\"claim\": \"Elasticsearch-compatible API is available on port 9200\", \"verified\": false}",
      "suggested_fix": "Downgrade coverage to 'partial' or provide source code/tests proving the ES-compat layer implementation. Change evidence_status to 'inferred'."
    },
    {
      "severity": "high",
      "claim": "MCP Server Integration coverage=full, evidence_status=declared",
      "problem": "The passport claims full MCP support based on README and dsh/package.json. The package.json describes a 'DeepSeek Harness (dsh) profile bundle' that 'inserts the xerj MCP server'. This suggests MCP is an integration feature or requires a specific harness, not necessarily a native, standalone capability of the core engine. The evidence_status 'declared' is weak for a 'full' coverage claim.",
      "evidence": "dsh/package.json@50e4ffde: \"description\": \"DeepSeek Harness (dsh) profile bundle that inserts the xerj MCP server over stdio.\"",
      "suggested_fix": "Clarify if MCP is native to the engine or an integration. If native, provide source evidence from crates/xerj-mcp. If integration-only, mark coverage as 'partial'."
    },
    {
      "severity": "medium",
      "claim": "Full-Text Search coverage=full, evidence_status=verified",
      "problem": "The claim is marked 'verified' with evidence from README and search.rs. However, the provided evidence_refs are documentation/marketing (README) and a CLI client wrapper (search.rs), not the core indexing/search engine implementation code (e.g., xerj-fts crate). Verification should ideally point to the core logic.",
      "evidence": "evidence_refs: [\"README.md@50e4ffde\", \"engine/crates/xerj-autoindex/src/search.rs@50e4ffde\"]",
      "suggested_fix": "Update evidence_refs to include source files from the xerj-fts crate or core search implementation to substantiate 'verified' status."
    },
    {
      "severity": "medium",
      "claim": "License: apache-2.0",
      "problem": "The passport lists license as 'apache-2.0'. The LICENSE file excerpt is truncated in the evidence ('...Legal Entity\" shall mean the union of the acting entity and all'). While likely correct, the evidence provided is incomplete for a definitive audit.",
      "evidence": "LICENSE@50e4ffde (truncated)",
      "suggested_fix": "Provide full license text or confirm via metadata API if available."
    }
  ]
}
